local config = {
  ui_story_31170401_1_dialog_content = "You see, Vice? I told you our Navigator didn't look well today.",
  ui_story_31170401_2_dialog_content = "Pale face, chapped lips... Even PlayerName's hair looks a mess.",
  ui_story_31170401_3_dialog_content = "You're absolutely right. It's been days since the Navigator ate properly.",
  ui_story_31170401_4_dialog_content = "Today was no different... The bread they served this morning, PlayerName didn't even take a bite.",
  ui_story_31170401_5_dialog_content = "It's true, I haven't had much of an appetite lately... I've been feeling really weak for some reason, too...",
  ui_story_31170401_6_dialog_content = "Let me have a look.",
  ui_story_31170401_7_dialog_content = "No fever.",
  ui_story_31170401_8_dialog_content = "Mr. Gram...",
  ui_story_31170401_9_dialog_content = "Just \"Gram\" will do.",
  ui_story_31170401_10_dialog_content = "G-Gram... Can you let go of my eyelids, please?",
  ui_story_31170401_11_dialog_content = "The whites of your eyes don't look too good, either... How have you been sleeping lately?",
  ui_story_31170401_12_dialog_content = "I remember your lights were still on really late last night, Navigator.",
  ui_story_31170401_13_dialog_content = "What time did you go to bed last night?",
  ui_story_31170401_14_dialog_content = "I can't recall... I just remember lying down for a second, and the next second you two were calling me.",
  ui_story_31170401_15_dialog_content = "I'd say I slept two, three hours, maybe?",
  ui_story_31170401_16_dialog_content = "But it's fine, trust me! I've gotten used to it these last few days. I just felt a little tired when I first got out of bed, that's all.",
  ui_story_31170401_17_dialog_content = "How long have you been maintaining this kind of routine?",
  ui_story_31170401_18_dialog_content = "About a week.",
  ui_story_31170401_19_dialog_content = "That's around the time you started losing your appetite, too.",
  ui_story_31170401_20_dialog_content = "Understood. I've seen this before, actually. We call it <color=#FFB400>Body Function Disorder</color>, or BFD.",
  ui_story_31170401_21_dialog_content = "Plenty of new soldiers come down with it. Luckily, I happen to have the <color=#FFB400>cure</color>.",
  ui_story_31170401_22_dialog_content = "Vice, it looks like PlayerName won't be able to work. What about the Colossus?",
  ui_story_31170401_23_dialog_content = "I'll handle the Navigator's responsibilities for the time being.",
  ui_story_31170401_24_dialog_content = "What... kind of cure? Is it bitter?",
  ui_story_31170401_25_dialog_content = "Not at all, but it can be a little taxing. Let's see if you can handle it.",
  ui_story_31170401_26_option_content = "Taxing...?",
  ui_story_31170401_27_dialog_content = "How can taking medicine be taxing? Do I have to eat a ridiculously big pill or something?",
  ui_story_31170401_28_dialog_content = "If only it were that easy...",
  ui_story_31170401_29_dialog_content = "This cure will affect every nerve as well as every muscle in your body and dramatically increase blood circulation. You'll feel like an entirely new person after taking it.",
  ui_story_31170401_30_option_content = "Handle it...?",
  ui_story_31170401_31_dialog_content = "It's not bitter, but why does it still sound so awful?",
  ui_story_31170401_32_dialog_content = "Is it really spicy like wasabi or something?",
  ui_story_31170401_33_dialog_content = "It's not spicy in the least, although it will definitely make you sweat like never before.",
  ui_story_31170401_34_dialog_content = "Back in the day, I used to take it all the time... So you can trust me when I tell you that it works wonders on the body.",
  ui_story_31170401_35_dialog_content = "But first, I need to see just how disordered your bodily functions have become.",
  ui_story_31170401_36_dialog_content = "A simple test will do.",
  ui_story_31170401_37_dialog_content = "What kind of test?",
  ui_story_31170401_38_dialog_content = "Oh, we can do all kinds, actually! Endurance tests, lower-body coordination tests, balance tests, arm strength tests...",
  ui_story_31170401_39_dialog_content = "We'll do all of them, one after another!",
  ui_story_31170401_40_dialog_content = "Now then, let's start with testing your physical endurance by having you carry water.",
  ui_story_31170401_41_dialog_content = "Haah... Haah... Haah...",
  ui_story_31170401_42_dialog_content = "You still have two buckets left! Come on, no stopping!",
  ui_story_31170401_43_dialog_content = "Haah... Haah... Haah...",
  ui_story_31170401_44_dialog_content = "We can test your arm strength by making you chop wood. The motion is simple enough: Raise your arms high, then swing down fiercely!",
  ui_story_31170401_45_dialog_content = "The key is to be both fast and accurate!",
  ui_story_31170401_46_dialog_content = "Remember! Each log must be split into four equally-sized pieces!",
  ui_story_31170401_47_dialog_content = "Yes, sir...",
  ui_story_31170401_48_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_31170401_49_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_31170401_X49_dialog_content = "Next is picking peas!",
  ui_story_31170401_50_dialog_content = "My shoulders are so sore...",
  ui_story_31170401_51_dialog_content = "Kids these days are really lacking when it comes to physical training. Look at you! We've barely started, and your arms are already trembling like a baby deer's legs!",
  ui_story_31170401_52_dialog_content = "Don't stop yet! You still have all these peas to pick, now hurry it up!",
  ui_story_31170401_53_dialog_content = "But there are way too many of them! Way more than a single person can handle...",
  ui_story_31170401_54_dialog_content = "The enemy won't tolerate all your complaining and excuses in a real battle.",
  ui_story_31170401_55_dialog_content = "You have a point, but still...",
  ui_story_31170401_56_dialog_content = "You need to believe in yourself... in your tenacity and your perseverance! Remember, you gave your word that you would finish this!",
  ui_story_31170401_57_dialog_content = "Now get picking, and don't let any go to waste!",
  ui_story_31170401_58_dialog_content = "*Sobbing* Why do I have to do this...?",
  ui_story_31170401_59_dialog_content = "I wouldn't have agreed to take his tests if I knew this was what I had to do... I just didn't have an appetite, that's all...",
  ui_story_31170401_60_dialog_content = "You still have five pieces of meat left! Keep chopping!",
  ui_story_31170401_61_dialog_content = "What kind of test is this, Gram?! You're just making me do your job at this point, aren't you?!",
  ui_story_31170401_62_dialog_content = "Carrying water, chopping wood, picking peas... And now, chopping meat? You're just using me as your assistant!",
  ui_story_31170401_63_dialog_content = "Heh... Not just anyone has what it takes to be my assistant, you know?",
  ui_story_31170401_64_dialog_content = "Wait... What's that amazing smell...?",
  ui_story_31170401_65_dialog_content = "Thanks to all the tests we did just now, I was able to fully understand your body's current condition and prepare this for you.",
  ui_story_31170401_66_dialog_content = "Here.",
  ui_story_31170401_67_dialog_content = "Fried rice with meat and peas...?",
  ui_story_31170401_68_dialog_content = "(Gurgle, gurgle)",
  ui_story_31170401_69_dialog_content = "Looks like you've got your appetite back. Why don't you take this back to your room...",
  ui_story_31170401_70_dialog_content = "*Munch*",
  ui_story_31170401_71_dialog_content = "Delicious!!",
  ui_story_31170401_72_dialog_content = "How could something this delicious exist in the world?! The meat is fried perfectly!",
  ui_story_31170401_73_dialog_content = "The meat is fatty but not too greasy, the peas are crisp and flavorful, and each roasted grain of rice stands out perfectly from the others...",
  ui_story_31170401_74_dialog_content = "*Munch*",
  ui_story_31170401_75_dialog_content = "Or you can just eat it here. Looks like my words aren't reaching you at the moment, anyway.",
  ui_story_31170401_76_dialog_content = "*Gobble* How... How could something taste so amazing...?! *Munch*",
  ui_story_31170401_77_dialog_content = "Hey, slow down a little. Don't talk with your mouth full!",
  ui_story_31170401_78_dialog_content = "*Burp*",
  ui_story_31170401_79_dialog_content = "Did you really make that fried rice, Gram? *Belch* I had no idea... that you were such a master cook!",
  ui_story_31170401_80_dialog_content = "Hahaha! I spent a lot of my military years working in the mess halls, kid! This was nothing, I'm pretty sure I've fed every single person in the Undercities at least once!",
  ui_story_31170401_81_dialog_content = "I never would have guessed... *Gulp*",
  ui_story_31170401_82_dialog_content = "Ahem... I'm glad you liked it, but you don't really need to lick the plate clean.",
  ui_story_31170401_83_dialog_content = "Oh, right! When am I supposed to take my medicine, Gram?",
  ui_story_31170401_84_dialog_content = "Your medicine, huh... We'll talk about it tomorrow.",
  ui_story_31170401_85_dialog_content = "For now, why don't you go hop in the shower and get a little more sleep?",
  ui_story_31170401_86_dialog_content = "Well, I am feeling pretty tired... I'll go do that then, Gram.",
  ui_story_31170401_87_dialog_content = "Good morning, PlayerName!",
  ui_story_31170401_88_dialog_content = "Hey, Vice! Good morning!",
  ui_story_31170401_89_dialog_content = "You're up early today, PlayerName. Feeling better?",
  ui_story_31170401_90_dialog_content = "Good morning, Gram.",
  ui_story_31170401_91_dialog_content = "Yeah, much better! When I got up this morning, I felt so awake and full of energy. I don't think I need to take any medicine today!",
  ui_story_31170401_92_dialog_content = "Young people do bounce back really quick... Looks like my cure worked, after all!",
  ui_story_31170401_93_dialog_content = "Huh?",
  ui_story_31170401_94_dialog_content = "Put simply, you took your medicine yesterday. Understand?",
  ui_story_31170401_95_option_content = "I understand.",
  ui_story_31170401_96_dialog_content = "Those tests yesterday, they were work as well as exercises, weren't they?",
  ui_story_31170401_97_dialog_content = "And when we sat down to eat... that was around dinner-time, wasn't it?",
  ui_story_31170401_98_dialog_content = "Tired and full, I fell asleep as soon as I laid in bed... and I stayed asleep for a whole eight hours.",
  ui_story_31170401_99_dialog_content = "That means, <color=#FFB400>the best cure is regular exercise and a good daily routine</color>!",
  ui_story_31170401_100_option_content = "Not really...",
  ui_story_31170401_101_dialog_content = "(Ahem) Do you remember what time you had your dinner?",
  ui_story_31170401_102_dialog_content = "I think it was late in the afternoon...",
  ui_story_31170401_103_dialog_content = "Those tests you took during the day... they were actually just physical labor.",
  ui_story_31170401_104_dialog_content = "Throw in a healthy dinner and a good night's rest, and you're back to your normal self!",
  ui_story_31170401_105_dialog_content = "I see... I get it now! <color=#FFB400>The best cure is regular exercise and a good daily routine</color>.",
  ui_story_31170401_106_dialog_content = "That's right!",
  ui_story_31170401_107_dialog_content = "Thank you, Gram!",
  ui_story_31170401_108_dialog_content = "I'm just glad you're feeling better. Do remember that your body is your own responsibility, but don't forget that other people are also counting on you.",
  ui_story_31170401_109_dialog_content = "Especially when it comes to battle. For your friends' sake, you can't afford to let your body get back in that state. Understood?",
  ui_story_31170401_110_option_content = "Understood!",
  ui_story_31170401_111_dialog_content = "If I let myself get that tired and weak, it could seriously affect my ability to give orders.",
  ui_story_31170401_112_dialog_content = "In that case, even the smallest mistake could cost you dearly. The price may even have to be paid in blood...",
  ui_story_31170401_113_dialog_content = "You're right... I'll take better care of myself from now on!",
  ui_story_31170401_114_option_content = "But why?",
  ui_story_31170401_115_dialog_content = "You're in charge of commanding us in battle, remember?",
  ui_story_31170401_116_dialog_content = "If something goes wrong... It's possible that...",
  ui_story_31170401_117_dialog_content = "It could have serious consequences.",
  ui_story_31170401_118_dialog_content = "I understand now. I won't let myself get back in that state ever again.",
  ui_story_31170401_119_dialog_content = "As long as you understand.",
  ui_story_31170401_120_dialog_content = "Now then, since you're nice and cured now, I think it's time for me to take my leave.",
  ui_story_31170401_121_dialog_content = "He took off so quickly... I didn't even get the chance to properly thank him yet.",
  ui_story_31170401_122_dialog_content = "Gram isn't the type to accept gratitude like that. As long as you're feeling better, that's more than enough for him.",
  ui_story_31170401_123_dialog_content = "Don't let his lackadaisical demeanor fool you. He's extremely watchful over the well-being of his friends.",
  ui_story_31170401_124_dialog_content = "The <color=#FFB400>Soldier's Fried Rice</color> he made for you yesterday is his best dish. It's packed with nutrients and is super healthy to boot!",
  ui_story_31170401_125_dialog_content = "So that's what it's called... It was so delicious! I don't think I'll ever forget the taste...",
  ui_story_31170401_126_dialog_content = "Before he cooked that dish for me, I thought Gram was just an ordinary veteran who served as a logistics manager.",
  ui_story_31170401_127_dialog_content = "He has such a long and eventful history... When he first joined the military, he served as a cook for a few years before turning to the defensive line to fend off Eclipsite attacks...",
  ui_story_31170401_128_dialog_content = "After retiring from the military, he started working in logistics, where he also rediscovered his love for cooking. All those years of experience and training... It's incredible!",
  ui_story_31170401_129_dialog_content = "But his Soldier's Fried Rice is reserved for the sick. I've only had it once in my life, too.",
  ui_story_31170401_130_dialog_content = "I even thought about staying up late for the next few days, just so he would make it for me again...",
  ui_story_31170401_131_dialog_content = "Think it's worth it, PlayerName?",
  ui_story_31170401_132_dialog_content = "I-I don't think so...",
  ui_story_31170401_133_dialog_content = "The Soldier's Fried Rice might taste amazing, but those tests were way too exhausting...",
  ui_story_31170601_1_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_2_dialog_content = "No, just hang on! I'm not going down yet—",
  ui_story_31170601_3_dialog_content = "<size=45>Not going down—Aaaaahhh!</size>",
  ui_story_31170601_4_dialog_content = "<size=45>NOOOO—</size>",
  ui_story_31170601_5_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_6_dialog_content = "<color=#e8d9bb>Fifteen minutes ago</color>",
  ui_story_31170601_7_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_8_dialog_content = "Oh, what refreshing air. I haven't come to a valley this serene and beautiful in a long time.",
  ui_story_31170601_9_dialog_content = "But is it our final destination? I thought it was training? Or...",
  ui_story_31170601_10_dialog_content = "You're finally showing compassion and taking the opportunity to take me to sightsee?",
  ui_story_31170601_11_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_31170601_12_dialog_content = "Gram?!",
  ui_story_31170601_13_dialog_content = "W-Where are you? You didn't just accidentally fall into the lake, did you? Don't freak me out here!",
  ui_story_31170601_14_dialog_content = "You know, the name Gram and \"accidentally fall\" don't belong in the same sentence. Why don't you join me?",
  ui_story_31170601_15_dialog_content = "Huh? Wait, no, don't pull me into the water—!",
  ui_story_31170601_16_dialog_content = "Open your eyes and see, kid. It's not even knee-deep.",
  ui_story_31170601_17_dialog_content = "You're right... Haha, it's nice to play in the water like this sometimes.",
  ui_story_31170601_18_dialog_content = "I knew you'd like it.",
  ui_story_31170601_19_dialog_content = "But don't get it wrong, this is our natural training ground.",
  ui_story_31170601_20_dialog_content = "See that waterfall? Go stand in that!",
  ui_story_31170601_21_dialog_content = "What kind of training is this?",
  ui_story_31170601_22_dialog_content = "As a frontline soldier, you must be calm and hold on till the end, no matter what's coming at you.",
  ui_story_31170601_23_dialog_content = "Maintaining your posture under the rushing cascade without moving is the best way to hone that discipline.",
  ui_story_31170601_24_dialog_content = "I call the training, \"Warriors Never Fall.\"",
  ui_story_31170601_25_dialog_content = "It's a battle against nature as well as between you and me.",
  ui_story_31170601_26_dialog_content = "Come, PlayerName! Whoever gets off their feet first will be responsible for cooking today.",
  ui_story_31170601_27_dialog_content = "What? But I've been craving your cooking and that's why I agreed to the training!",
  ui_story_31170601_28_dialog_content = "So you don't think you have any chance of beating me?",
  ui_story_31170601_29_option_content = "I'll give myself a chance somehow!",
  ui_story_31170601_30_dialog_content = "I've got to believe there's a chance, however small. Otherwise, I won't beat you at all!",
  ui_story_31170601_31_option_content = "That's because you're too tough for me!",
  ui_story_31170601_32_dialog_content = "Still, I have to give it a shot.",
  ui_story_31170601_33_dialog_content = "I'll get my hands on your cooking!",
  ui_story_31170601_34_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_35_dialog_content = "Ahh! The impact is greater than I thought...",
  ui_story_31170601_36_dialog_content = "I'm almost... at my limit...",
  ui_story_31170601_37_dialog_content = "No, just hang on! I'm not going down yet—",
  ui_story_31170601_38_dialog_content = "<size=45>Not going down—Aaaaahhh!</size>",
  ui_story_31170601_39_dialog_content = "<size=45>NOOOO—</size>",
  ui_story_31170601_40_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_41_dialog_content = "<size=45><color=#e8d9bb>Splash!</color></size>",
  ui_story_31170601_42_dialog_content = "Hahaha! Not bad, kid, you hung on much longer than I expected.",
  ui_story_31170601_43_dialog_content = "(How can Gram still be standing like a wall in the waterfall after such a long time?)",
  ui_story_31170601_44_dialog_content = "(Sigh, it's to be expected, really. I'm not even in the same league as him...)",
  ui_story_31170601_45_dialog_content = "Alright, the dinner is in your hands now!",
  ui_story_31170601_46_dialog_content = "This training is too difficult for me. It's impossible for me to win without the physical and strength advantages you have.",
  ui_story_31170601_47_dialog_content = "PlayerName, you've been to Illumina's frontline, so you know we got scrawny guys in the army.",
  ui_story_31170601_48_dialog_content = "And when they fought, they fought just as well as me. Do you know why?",
  ui_story_31170601_49_dialog_content = "... Yes, Gram, I know what you're getting at. I won't make any more excuses.",
  ui_story_31170601_50_dialog_content = "You always find the source of a problem in the shortest time, which was why I agreed to take you out for training.",
  ui_story_31170601_51_dialog_content = "Ever since I became a drill instructor, I've gotten to see more and more quality youngsters.",
  ui_story_31170601_52_dialog_content = "In turn, I make tougher demands than before, so you better bring your \"A\" game!",
  ui_story_31170601_53_dialog_content = "I almost forgot that you're the instructor for the new recruits now!",
  ui_story_31170601_54_dialog_content = "No wonder there's something different about you... What's been going on?",
  ui_story_31170601_55_dialog_content = "You're interested?",
  ui_story_31170601_56_dialog_content = "Then go make dinner now. Make sure you do the physical conditioning test that I showed you before.",
  ui_story_31170601_57_dialog_content = "Physical conditioning test? You mean the exercise routine before cooking?",
  ui_story_31170601_58_dialog_content = "Can't escape your regimen even when I lose, I see...",
  ui_story_31170601_59_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_31170601_60_dialog_content = "*burp*",
  ui_story_31170601_61_dialog_content = "I didn't expect tasting fine food out in nature to be such an enjoyment.",
  ui_story_31170601_62_dialog_content = "It's a double enjoyment on the spiritual and physical levels that you get only after putting all your effort into training.",
  ui_story_31170601_63_dialog_content = "So, how about coming out with me more often?",
  ui_story_31170601_64_dialog_content = "By that, you really mean come out and train with you, right?",
  ui_story_31170601_65_dialog_content = "Oh, right, Gram, speaking of which, did anything interesting happen?",
  ui_story_31170601_66_dialog_content = "I've told you what stuck out most in my head. As for the rest...",
  ui_story_31170601_67_dialog_content = "The higher-ups revamped everyone's regular gear again. Revy went on her own mission. Ansia finally figured out the switch for the speaker...",
  ui_story_31170601_68_dialog_content = "And me, I got around to understanding the choice Brent made.",
  ui_story_31170601_69_dialog_content = "Seeing all these youngsters I know grow up so quickly feels good. I'm happier and prouder than winning a battle.",
  ui_story_31170601_70_dialog_content = "Although I'd get bad news sometimes and had to attend a few burials.",
  ui_story_31170601_71_dialog_content = "Watching the names of the soldiers I trained on the tombstones does raise doubt about whether I should continue to be an instructor.",
  ui_story_31170601_72_dialog_content = "In my or Brent's case, we curmudgeons lived long enough to have no regret in sacrificing ourselves whatsoever.",
  ui_story_31170601_73_dialog_content = "But every one of the new recruits is as clean as a new sheet.",
  ui_story_31170601_74_dialog_content = "I just can't stand seeing those youngsters losing their lives... You know, Brent would chew me out for thinking this way.",
  ui_story_31170601_75_dialog_content = "But what can you do, other than being tough, then even tougher when I train them?",
  ui_story_31170601_76_dialog_content = "Turn the rookies into warriors before they get on the battlefield so they don't have to make unnecessary sacrifices.",
  ui_story_31170601_77_dialog_content = "I see now you meant well... But have you considered going back to the front?",
  ui_story_31170601_78_dialog_content = "With how unbeatable and indomitable you are, you can easily become a role model for soldiers, and even a figure on par with the commanders!",
  ui_story_31170601_79_dialog_content = "That's quite all right. I vowed long ago to finish what Brent couldn't. And...",
  ui_story_31170601_80_dialog_content = "\"Warriors never fall\" doesn't mean an always unbeatable and indomitable soldier.",
  ui_story_31170601_81_dialog_content = "But aren't you one yourself?",
  ui_story_31170601_82_dialog_content = "I'm a mortal Aurorian with my own weakness too. Truly unbeatable, indomitable warriors don't exist.",
  ui_story_31170601_83_dialog_content = "But \"warriors never fall\" is not a slogan I use to fool you.",
  ui_story_31170601_84_dialog_content = "The small picture is maybe thousands and thousands of warriors will ultimately fall in battle.",
  ui_story_31170601_85_dialog_content = "But the big picture is there will be thousands and thousands more to take their place!",
  ui_story_31170601_86_dialog_content = "That's what \"warriors never fall\" really means!",
  ui_story_31170601_87_dialog_content = "Wow, you just got very profound there very quickly...",
  ui_story_31170601_88_dialog_content = "It's probably because you've been training people for a while.",
  ui_story_31170601_89_dialog_content = "Yes, and there's something I've been thinking for quite some time now...",
  ui_story_31170601_90_dialog_content = "You must hone both your physical attributes and psychic abilities at the same time.",
  ui_story_31170601_91_dialog_content = "T-That sounds hard...",
  ui_story_31170601_92_dialog_content = "But no problem! If I fall, I'll just get right back up, since...",
  ui_story_31170601_93_dialog_content = "Warriors! Never! Fall!",
  ui_story_31170601_94_dialog_content = "Hahaha, alright! You're a quick learner, kid!"
}
return config
